function boolean holiday(date d){string k=date2str(d,"yyyy-MM-dd","en.US","UTC");return k=="2026-03-30" || k=="2026-04-01" || k=="2026-12-31" || k=="2027-01-01";}
function string calendar(date d){date dayStart=createDate(getYear(d,"UTC"),getMonth(d,"UTC"),getDay(d,"UTC"),"UTC");while(getDayOfWeek(dayStart,"UTC")>5 || holiday(dayStart))dayStart=dateAdd(dayStart,-86400000L,millisec);return date2str(dayStart,"yyyy-MM-dd","en.US","UTC");}
