decimal roundedSum;decimal postedAmount;boolean postedValid;
function void initGroup(UrnAccumulator acc){seen=0;bad=0;good=0;total=0D;started=false;history=false;roundedSum=0D;}
function boolean updateGroup(UrnAccumulator acc){if(!started){first_lot=$in.0.urn_project;first_piece=$in.0.sherd_tag;first_at=$in.0.restored_dt;first_steward=$in.0.archaeologist_name;first_archive=$in.0.excavation_reference;first_order=$in.0.task_order;first_note=$in.0.pottery_note;started=true;}seen++;decimal amount=null;decimal factor=1D;string verdict="VALID";string factorText=isnull($in.0.labour_factor) ? "" : trim($in.0.labour_factor);
if(factorText!=""){if(!(factorText ~= "-?[0-9]{1,6}(\\.[0-9]{1,3})?"))verdict="TEXT";else factor=str2decimal(factorText);}
if(verdict=="VALID" && isnull($in.0.labour_charge))verdict="MISSING";if(verdict=="VALID")amount=$in.0.labour_charge*factor;
if(verdict=="VALID"){good++;total+=amount;history=true;valid_lot=$in.0.urn_project;valid_piece=$in.0.sherd_tag;valid_at=$in.0.restored_dt;valid_steward=$in.0.archaeologist_name;valid_archive=$in.0.excavation_reference;valid_order=$in.0.task_order;valid_note=$in.0.pottery_note;}else bad++;if(verdict=="VALID")roundedSum+=round(amount,2);postedAmount=amount;postedValid=verdict=="VALID";return true;}
function integer updateTransform(integer counter,UrnAccumulator acc){if(!postedValid || counter>0)return SKIP;$out.0.urn_project=$in.0.urn_project;$out.0.sherd_tag=$in.0.sherd_tag;$out.0.restored_dt=$in.0.restored_dt;$out.0.archaeologist_name=$in.0.archaeologist_name;$out.0.excavation_reference=$in.0.excavation_reference;$out.0.task_order=$in.0.task_order;$out.0.pottery_note=$in.0.pottery_note;$out.0.posting_category="CHARGE";$out.0.posting_amount=round(postedAmount,2);$out.0.amount_change=null;$out.0.tasks_received=seen;$out.0.defective_tasks=bad;$out.0.working_date=calendar($in.0.restored_dt);return 0;}
function boolean finishGroup(UrnAccumulator acc){return true;}
function integer transform(integer counter,UrnAccumulator acc){key=calendar(first_at);if(counter>0)return SKIP;$out.0.urn_project=first_lot;$out.0.sherd_tag=first_piece;$out.0.restored_dt=first_at;$out.0.archaeologist_name=first_steward;$out.0.excavation_reference=first_archive;$out.0.task_order=first_order;$out.0.pottery_note=first_note;$out.0.posting_category="RESIDUAL";$out.0.posting_amount=total-roundedSum;$out.0.amount_change=null;$out.0.tasks_received=seen;$out.0.defective_tasks=bad;$out.0.working_date=key;return 0;}

